(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-001":{scenario:{legacy:"A"},learning:{summary:{vi:"Quản trị viên hệ thống CNTT vận hành, bảo trì và bảo mật máy chủ Linux, Windows Server, dịch vụ thư mục Active Directory, lưu trữ, sao lưu và ảo hóa của doanh nghiệp. Công việc gồm cài đặt, vá lỗi, giám sát, quản lý tài khoản và quyền truy cập, xử lý sự cố và thực hiện thay đổi theo quy trình được phê duyệt. Yêu cầu cốt lõi: chẩn đoán có hệ thống, kỷ luật sao lưu, ghi nhật ký và nguyên tắc đặc quyền tối thiểu.",en:"An IT system administrator runs, maintains and secures a company's Linux and Windows servers, Active Directory, storage, backup and virtualization. The work covers installation, patching, monitoring, account and access management, incident handling and changes made through an approved process. Core requirements: systematic diagnosis, backup and logging discipline and the principle of least privilege."},responsibilities:{vi:["Cài đặt, cấu hình và cập nhật bản vá cho máy chủ Linux, Windows Server theo lịch bảo trì.","Quản lý tài khoản, nhóm, chính sách nhóm (GPO) và quyền truy cập theo nguyên tắc đặc quyền tối thiểu.","Giám sát CPU, bộ nhớ, ổ đĩa, dịch vụ và xử lý cảnh báo, sự cố theo mức ưu tiên.","Vận hành sao lưu, kiểm thử khôi phục định kỳ và duy trì kế hoạch phục hồi thảm họa.","Thực hiện thay đổi qua phiếu được phê duyệt, cập nhật tài liệu cấu hình và sơ đồ hệ thống."],en:["Install, configure and patch Linux and Windows servers on a maintenance schedule.","Manage accounts, groups, Group Policy (GPO) and access on a least-privilege basis.","Monitor CPU, memory, disks and services and handle alerts and incidents by priority.","Run backups, test restores regularly and maintain the disaster recovery plan.","Make changes through approved tickets and keep configuration documents and diagrams current."]},competencies:[{name:{vi:"Quản trị Linux",en:"Linux administration"},desc:{vi:"Làm chủ systemd, quyền tệp, LVM, SSH bằng khóa, nhật ký hệ thống và quản lý gói.",en:"Master systemd, file permissions, LVM, key-based SSH, system logs and package management."}},{name:{vi:"Windows Server & AD",en:"Windows Server & AD"},desc:{vi:"Vận hành Active Directory, DNS, DHCP, GPO và phân quyền NTFS, chia sẻ tệp.",en:"Operate Active Directory, DNS, DHCP, GPO and NTFS and share permissions."}},{name:{vi:"Tự động hóa bằng script",en:"Scripting & automation"},desc:{vi:"Viết Bash, PowerShell, Ansible để triển khai đồng nhất và giảm thao tác thủ công.",en:"Write Bash, PowerShell and Ansible to deploy consistently and reduce manual work."}},{name:{vi:"Sao lưu & phục hồi",en:"Backup & recovery"},desc:{vi:"Thiết kế lịch sao lưu theo RPO, RTO, giữ bản sao ngoại tuyến và diễn tập khôi phục.",en:"Design backups around RPO and RTO, keep offline copies and rehearse restores."}},{name:{vi:"Bảo mật & tuân thủ",en:"Security & compliance"},desc:{vi:"Cứng hóa máy chủ, bật MFA cho tài khoản quản trị, giữ nhật ký kiểm toán và vá lỗ hổng đúng hạn.",en:"Harden servers, enforce MFA on admin accounts, keep audit logs and patch vulnerabilities on time."}}],knowledge:{vi:["ITIL 4: quản lý sự cố, quản lý thay đổi (change enablement) và quản lý cấu hình.","CIS Benchmarks và CIS Controls cho cấu hình an toàn hệ điều hành và dịch vụ.","ISO/IEC 27001:2022 với các biện pháp kiểm soát về truy cập, sao lưu, ghi nhật ký và quản lý lỗ hổng.","Quy tắc sao lưu 3-2-1: 3 bản sao, 2 loại phương tiện, 1 bản ngoài cơ sở; thêm bản bất biến chống mã độc tống tiền.","Mô hình quyền tệp Linux (rwx, chmod dạng số) và quyền NTFS kế thừa trên Windows.","Quy định hiện hành của Việt Nam về bảo đảm an toàn hệ thống thông tin theo cấp độ."],en:["ITIL 4: incident management, change enablement and configuration management.","CIS Benchmarks and CIS Controls for secure operating system and service configuration.","ISO/IEC 27001:2022 controls for access, backup, logging and vulnerability management.","The 3-2-1 backup rule: 3 copies, 2 media types, 1 off-site; plus an immutable copy against ransomware.","The Linux permission model (rwx, numeric chmod) and inherited NTFS permissions on Windows.","Current Vietnamese rules on securing information systems by protection level."]},tools:["Bash / systemd","PowerShell","Active Directory","Ansible","Zabbix / Prometheus","Nền tảng ảo hóa & sao lưu"],kpis:{vi:["Độ sẵn sàng của dịch vụ theo SLA (ví dụ từ 99,9% trở lên).","Tỷ lệ máy chủ được vá trong thời hạn quy định.","Tỷ lệ diễn tập khôi phục thành công và đạt RTO.","Thời gian khôi phục trung bình (MTTR) của sự cố hạ tầng."],en:["Service availability against the SLA (for example 99.9% or higher).","Share of servers patched within the required window.","Share of restore drills that succeed within the RTO.","Mean time to restore (MTTR) for infrastructure incidents."]},day:[{time:"08:00",vi:"Kiểm tra bảng giám sát, kết quả sao lưu đêm và cảnh báo dung lượng ổ đĩa.",en:"Check the monitoring board, overnight backup results and disk space alerts."},{time:"09:30",vi:"Xử lý phiếu tạo tài khoản, cấp quyền thư mục và đặt lại mật khẩu đã xác minh.",en:"Handle tickets for new accounts, folder access and verified password resets."},{time:"11:00",vi:"Trình bày phiếu thay đổi bản vá tại họp CAB kèm kế hoạch hoàn tác.",en:"Present a patch change at the CAB meeting with a rollback plan."},{time:"14:00",vi:"Vá máy chủ thử nghiệm, viết script Ansible áp cấu hình cứng hóa.",en:"Patch test servers and write an Ansible playbook for hardening settings."},{time:"16:30",vi:"Cập nhật tài liệu cấu hình, sơ đồ hệ thống và bàn giao ca.",en:"Update configuration docs and system diagrams and hand over the shift."}],mistakes:{vi:["Sửa trực tiếp trên production không có phiếu thay đổi và không có kế hoạch hoàn tác.","Sao lưu đều đặn nhưng không bao giờ thử khôi phục, đến khi cần mới biết bản sao lưu hỏng.","Dùng chung tài khoản quản trị hoặc cấp quyền admin rộng cho nhanh, bỏ qua MFA và nhật ký."],en:["Editing production with no change ticket and no rollback plan.","Backing up faithfully but never testing restores, discovering broken backups only when needed.","Sharing admin accounts or granting broad admin rights for speed, skipping MFA and logging."]},career:[{vi:"Kỹ thuật viên hỗ trợ hệ thống",en:"Systems support technician"},{vi:"Quản trị viên hệ thống CNTT",en:"IT system administrator"},{vi:"Kỹ sư hệ thống cao cấp / Trưởng nhóm hạ tầng",en:"Senior systems engineer / Infrastructure team lead"},{vi:"Quản lý hạ tầng CNTT / Kiến trúc sư hạ tầng",en:"IT infrastructure manager / Infrastructure architect"}],glossary:[{term:"GPO",vi:"Chính sách nhóm của Active Directory, áp cấu hình và quy định bảo mật cho người dùng, máy tính.",en:"Active Directory Group Policy that applies settings and security rules to users and computers."},{term:"systemd",vi:"Trình quản lý khởi động và dịch vụ trên Linux, điều khiển bằng lệnh systemctl.",en:"Linux init and service manager, controlled with the systemctl command."},{term:"LVM",vi:"Quản lý ổ đĩa logic trên Linux, cho phép mở rộng phân vùng và tạo snapshot linh hoạt.",en:"Linux logical volume manager for flexible resizing and snapshots."},{term:"Hardening",vi:"Cứng hóa: tắt dịch vụ thừa, siết cấu hình và quyền để giảm bề mặt tấn công.",en:"Disabling unneeded services and tightening settings and permissions to shrink the attack surface."},{term:"RPO / RTO",vi:"Lượng dữ liệu tối đa có thể mất và thời gian tối đa để khôi phục dịch vụ sau sự cố.",en:"Maximum acceptable data loss and maximum time to restore service after an incident."}],quiz:[{q:{vi:"Quy tắc sao lưu 3-2-1 nghĩa là gì?",en:"What does the 3-2-1 backup rule mean?"},options:{vi:["3 máy chủ, 2 ổ đĩa, 1 người phụ trách","Sao lưu 3 lần mỗi ngày, giữ 2 ngày, 1 bản nén","3 bản sao, 2 loại phương tiện, 1 bản ngoài cơ sở","3 tháng, 2 tuần, 1 ngày"],en:["3 servers, 2 disks, 1 owner","Back up 3 times daily, keep 2 days, 1 archive","3 copies, 2 media types, 1 off-site","3 months, 2 weeks, 1 day"]},answer:2,explain:{vi:"Giữ 3 bản sao dữ liệu trên 2 loại phương tiện khác nhau, trong đó 1 bản đặt ngoài cơ sở.",en:"Keep 3 copies of data on 2 different media types, with 1 copy off-site."}},{q:{vi:"Lệnh nào kiểm tra trạng thái dịch vụ sshd trên Linux dùng systemd?",en:"Which command checks the sshd service status on a systemd Linux host?"},options:{vi:["systemctl status sshd","chmod 755 sshd","ipconfig /all","gpupdate /force"],en:["systemctl status sshd","chmod 755 sshd","ipconfig /all","gpupdate /force"]},answer:0,explain:{vi:"systemctl status hiển thị trạng thái, tiến trình và nhật ký gần nhất của một dịch vụ systemd.",en:"systemctl status shows a systemd service's state, process and recent log lines."}},{q:{vi:"Đồng nghiệp đề nghị tắt kiểm soát truy cập và xóa nhật ký để khôi phục dịch vụ nhanh hơn. Bạn làm gì?",en:"A colleague suggests disabling access controls and deleting logs to restore service faster. What do you do?"},options:{vi:["Làm theo vì dịch vụ đang dừng","Chỉ xóa nhật ký, giữ kiểm soát truy cập","Tắt kiểm soát rồi bật lại sau","Giữ kiểm soát và nhật ký, thực hiện hoàn tác đã duyệt và báo cáo"],en:["Comply because the service is down","Delete only the logs, keep access controls","Disable controls and re-enable later","Keep controls and logs, apply the approved rollback and report"]},answer:3,explain:{vi:"Nhật ký là bằng chứng điều tra và kiểm soát truy cập bảo vệ hệ thống; khôi phục phải theo phương án đã phê duyệt.",en:"Logs are investigation evidence and access controls protect the system; recovery follows the approved plan."}},{q:{vi:"Quyền tệp Linux 640 có nghĩa là gì?",en:"What do the Linux file permissions 640 mean?"},options:{vi:["Mọi người đọc, ghi được","Chủ sở hữu đọc, ghi; nhóm chỉ đọc; người khác không có quyền","Chủ sở hữu chỉ đọc; nhóm đọc, ghi","Chỉ root được thực thi"],en:["Everyone can read and write","Owner read and write; group read only; others none","Owner read only; group read and write","Only root can execute"]},answer:1,explain:{vi:"6 = r+w (4+2) cho chủ sở hữu, 4 = r cho nhóm, 0 = không quyền cho người khác.",en:"6 = r+w (4+2) for the owner, 4 = r for the group, 0 = no rights for others."}}],tools_en:["Bash / systemd","PowerShell","Active Directory","Ansible","Zabbix / Prometheus","Virtualization & backup platforms"]}}})})(window.KKR);
